asm_0_130_n:		; #asm, Main.bas line 130 (normal)
            ld hl, (pa_thirdof_a)        ; base [131]
            ld de, 4		; Main.bas 132
            add hl, de          ; element 2 [133]
            ld e, (hl)		; Main.bas 134
            inc hl		; Main.bas 135
            ld d, (hl)		; Main.bas 136
            ld (var_thirdof_thirdof), de		; Main.bas 137
			ret			; end of #asm


